package co.edu.unbosque.horarios.api;
import co.edu.unbosque.horarios.domain.Section; import co.edu.unbosque.horarios.repository.*; import co.edu.unbosque.horarios.service.ParameterService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/sections") public class SectionController {
 private final SectionRepository sections;private final CourseRepository courses;private final AcademicPeriodRepository periods;private final TeacherRepository teachers;private final ParameterService parameters;
 public SectionController(SectionRepository s,CourseRepository c,AcademicPeriodRepository p,TeacherRepository t,ParameterService ps){sections=s;courses=c;periods=p;teachers=t;parameters=ps;}
 @PostMapping("/suggest") @PreAuthorize("hasAnyRole('DIRECCION','COMITE_AREA')") public ApiDtos.Suggestion suggest(@RequestBody @Valid ApiDtos.SuggestionRequest r){int target=parameters.integer("tamano_objetivo",40),tolerance=parameters.integer("tolerancia",10),max=(int)Math.ceil(target*(1+tolerance/100.0));int min=(int)Math.ceil(r.demanda()/(double)max),rec=min;return new ApiDtos.Suggestion(min,rec,r.demanda()/(double)min,r.demanda()/(double)rec);}
 @PostMapping("/generate") @PreAuthorize("hasAnyRole('DIRECCION','COMITE_AREA')") public java.util.List<Long> generate(@RequestBody @Valid ApiDtos.SuggestionRequest r){var c=courses.findById(r.cursoId()).orElseThrow();var p=periods.findById(r.periodoId()).orElseThrow();var t=teachers.findById(r.docenteId()).orElseThrow();int target=parameters.integer("tamano_objetivo",40);int count=(int)Math.ceil(r.demanda()/(double)target);int each=(int)Math.ceil(r.demanda()/(double)count);return java.util.stream.IntStream.rangeClosed(1,count).mapToObj(n->sections.save(new Section(c,p,t,n,each)).getId()).toList();}
}
